  "rationale": "Both forms are valid for the stated banking sense. Indonesian setoran tunai and Malaysian deposit tunai are established expressions meaning cash deposited into an account. The contrast is a useful difference in common terminology, not a false friend.",
  "claim_reviews": [
    {
      "subject": "Indonesian answer: setoran tunai",
      "conclusion": "Correct and natural for cash deposited into an account.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.bi.go.id/id/publikasi/peraturan/Documents/pbi_172415_f.pdf",
        "https://www.bca.co.id/id/bisnis/solusi/cash-management/Collection/Cash-Pickup"
      ]
    },
    {
      "subject": "Malaysian answer: deposit tunai",
      "conclusion": "Correct and established Malaysian banking terminology for cash deposit.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.maybank2u.com.my/maybank2u/malaysia/en/personal/services/agent_banking/agent_banking-bm.page",
        "https://www.bsn.com.my/page/interbank-cash-deposit-via-cdm-crm"
      ]
    },
    {
      "subject": "English cue and sense",
      "conclusion": "Cash deposit accurately cues money paid into an account in cash; the supplied sense removes potential ambiguity.",
      "material_risk": false,
      "evidence_refs": [
        "https://www.cimb.com.my/bm/personal/help-support/faq/self-service-banking/cash-deposit-machines/what-are-the-services-or-facilities-available-via-cash-deposit-machines.html"
      ]
    },
    {
      "subject": "Final relation and false-friend contrast",
      "conclusion": "Different-common-word is appropriate as a learner-oriented preference contrast. There is no false-friend distinction: both expressions share the same banking sense.",
      "material_risk": false,
      "evidence_limitation": "The relation judgment is based on parallel official banking usage rather than a corpus-frequency comparison."
    }
  ]
}
